{
  "framing_conflicto_politico_vs_tecnologico": {
    "definicion": "Consiste en presentar un tema tecnológico como una disputa política, resaltando intereses partidistas, ideológicos o geopolíticos y minimizando los aspectos técnicos. El enfoque dirige la atención del público hacia la confrontación entre grupos y aleja la discusión de los méritos o riesgos reales de la tecnología.",
    "ejemplo": "Cobertura de la implantación de redes 5G en EE. UU. en 2024 que enfatiza la supuesta amenaza china y las tensiones diplomáticas, en lugar de explicar la mejora de velocidad y la gestión del espectro.",
    "como_detectarla": [
      "1. Identifica si el titular o la narrativa destaca rivalidades políticas, partidos o naciones antes que la función tecnológica.",
      "2. Busca la ausencia de datos técnicos (especificaciones, beneficios, limitaciones) mientras se citan discursos políticos o controversias electorales.",
      "3. Verifica si la información se repite en medios con orientación política y no en fuentes especializadas en tecnología."
    ]
  },
  "omision_del_tema_IA": {
    "definicion": "Práctica editorial que excluye deliberadamente la mención de la inteligencia artificial cuando esta es relevante para la historia, desviando la atención hacia otros ángulos menos críticos o controvertidos.",
    "ejemplo": "Reportaje de junio 2024 sobre un nuevo algoritmo de recomendación de video que omite que el sistema está basado en IA de aprendizaje profundo, centrando la pieza en la \"personalización del contenido\" sin nombrar la tecnología subyacente.",
    "como_detectarla": [
      "1. Revisa el contexto de la noticia y detecta conceptos que habitualmente implican IA (algoritmos, automatización, aprendizaje automático).",
      "2. Comprueba si fuentes técnicas o académicas citan IA mientras el texto del medio no la menciona.",
      "3. Analiza la estructura del artículo: si hay un hueco informativo donde debería ir una explicación de IA, indica posible omisión."
    ]
  },
  "omision_contenido_tecnologico": {
    "definicion": "Eliminación intencional de datos, avances o impactos tecnológicos en la cobertura de un hecho, con el fin de simplificar la narrativa o evitar discusiones técnicas que podrían complicar la historia principal.",
    "ejemplo": "Artículo de abril 2024 sobre el rescate de una mina que menciona el uso de drones para localizar a los atrapados, pero no describe el tipo de dron, sus sensores ni la tecnología de mapeo utilizada.",
    "como_detectarla": [
      "1. Identifica menciones de herramientas o procesos que suelen involucrar tecnología (drones, sensores, blockchain, etc.).",
      "2. Busca fuentes externas (informes técnicos, comunicados de empresas) que detallen la tecnología y compáralas con la cobertura del medio.",
      "3. Evalúa si la información tecnológica ha sido reemplazada por descripciones vagas o por énfasis en la dimensión humana o política."
    ]
  },
  "infotainment_figuras_publicas": {
    "definicion": "Formato que combina información con entretenimiento, enfocándose en la vida personal, polémicas o estilo de figuras públicas, mientras el contenido sustancial del tema se reduce o se ignora.",
    "ejemplo": "Programa nocturno de septiembre 2024 que cubre la visita de un presidente a una fábrica de autos eléctricos, centrándose en los chistes sobre su peinado y anécdotas de su familia, con escasa información sobre la producción de baterías.",
    "como_detectarla": [
      "1. Analiza si el contenido prioriza anécdotas, apariencia o escándalos de la figura sobre datos del asunto tratado.",
      "2. Verifica la proporción de tiempo o espacio dedicado a la persona frente a la información temática (p.ej., datos de producción, cifras económicas).",
      "3. Observa el tono: humorístico, sensacionalista o estilo de tabloide, y comprueba si se usan recursos visuales llamativos para mantener la atención."
    ]
  },
  "agenda_setting_politica_deporte": {
    "definicion": "Estrategia mediática que sitúa la política y el deporte como los temas prioritarios de la agenda pública, relegando otros asuntos (cultura, ciencia, salud) a un segundo plano, a fin de moldear la percepción de lo que es importante en la sociedad.",
    "ejemplo": "Cobertura de enero 2024 de la elección de alcalde en una capital europea donde los titulares principales son los debates políticos y la victoria del equipo local en la liga de fútbol, mientras que la crisis hídrica regional recibe menciones menores en secciones secundarias.",
    "como_detectarla": [
      "1. Revisa la distribución de espacio o tiempo en los medios: ¿politica y deporte aparecen en la portada o en los bloques principales?",
      "2. Compara la frecuencia de aparición de otros temas (ciencia, educación, salud) en la misma edición o ciclo de noticias.",
      "3. Analiza si los algoritmos de recomendación o los boletines destacados priorizan contenidos políticos o deportivos sobre otros asuntos relevantes."
    ]
  }
}
